}

$hasFunctionLike = $tokens->isTokenKindFound(T_FUNCTION)
    || (\defined('T_FN') && $tokens->isTokenKindFound(T_FN));
if (!$hasFunctionLike) {
    return false;
}

$shouldRefresh = $tokens->isChanged() || $this->argumentInfoCacheHash !== $tokens->getCodeHash();

static $searchTokens = [
    ';',
    '{',
    '}',
    [T_FUNCTION],
    [T_OPEN_TAG],
    [T_OPEN_TAG_WITH_ECHO],
];
$functionIndex = $tokens->getPrevTokenOfKind($index, $searchTokens);
$prevToken = $tokens[$functionIndex];

if (!$prevToken->isGivenKind(T_FUNCTION)) {
    return false;
}

$argumentsStart = $tokens->getNextTokenOfKind($functionIndex, ['(']);
if (null === $argumentsStart || $index < $argumentsStart) {
    return true;
}

$blockLevel = 0;
$argumentsEnd = $argumentsStart;
$tokenCount = \count($tokens);
for ($cursor = $argumentsStart; $cursor < $tokenCount; ++$cursor) {
    if ($tokens[$cursor]->equals('(')) {
        ++$blockLevel;
    } elseif ($tokens[$cursor]->equals(')')) {
        --$blockLevel;
        if (0 === $blockLevel) {
            $argumentsEnd = $cursor;

            break;
        }
    }
}

if ($index > $argumentsEnd) {
    return true;
}

$argumentsAnalyzer = new ArgumentsAnalyzer();
foreach ($argumentsAnalyzer->getArguments($tokens, $argumentsStart, $argumentsEnd) as $start => $end) {
    if ($index < $start || $index > $end) {
        continue;
    }

    $argument = $this->getArgumentInfo($start, $end);
    $nameIndex = $argument->getNameIndex();
    $hasType = $argument->hasTypeAnalysis();
    if ($shouldRefresh) {
        return true;
    }

    if ($hasType) {
        return true;
    }

    return null === $nameIndex || $nameIndex !== $index;

